const { withGradleProperties } = require("expo/config-plugins");

/**
 * Give Gradle room to finish packaging the Android build.
 *
 * The generated default is `-Xmx2048m -XX:MaxMetaspaceSize=512m`, and the
 * ARM64 release build exhausts that metaspace very late — after the native
 * compilation has already succeeded — so the failure looks like a code problem
 * when it is only a memory ceiling.
 *
 * This belongs in a plugin rather than in `android/gradle.properties`, because
 * that directory is gitignored and regenerated by prebuild: an edit there is
 * lost on the next local prebuild and never reaches an EAS build at all.
 */
const JVM_ARGS = "-Xmx4096m -XX:MaxMetaspaceSize=2048m";

module.exports = function withGradleMemory(config) {
  return withGradleProperties(config, (gradleConfig) => {
    const properties = gradleConfig.modResults;
    const existing = properties.find(
      (item) => item.type === "property" && item.key === "org.gradle.jvmargs",
    );
    if (existing) existing.value = JVM_ARGS;
    else properties.push({ type: "property", key: "org.gradle.jvmargs", value: JVM_ARGS });
    return gradleConfig;
  });
};
